import { useEffect, useRef, useState } from "react";
import { lerp, clamp, ease } from "./helpers";

const DATA = [
  2.52, 2.61, 2.75, 2.88, 2.95, 3.10, 3.28, 3.45, 3.62, 3.85,
  4.10, 4.38, 4.70, 5.05, 5.45, 5.90, 6.40, 6.95, 7.55, 8.20,
  8.90, 9.30, 9.62, 9.85, 10.0
];

export default function FraudSection() {
  const [progress, setProgress] = useState(0);
  const sectionRef = useRef(null);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 768);
    checkMobile();
    window.addEventListener("resize", checkMobile);
    return () => window.removeEventListener("resize", checkMobile);
  }, []);

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current; if (!el) return;
      const rect = el.getBoundingClientRect();
      const p = clamp(-rect.top / (el.offsetHeight - window.innerHeight), 0, 1);
      setProgress(p);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  // Fraud section progress variables
  const titleP  = ease(clamp(progress / 0.25, 0, 1));
  const chartP  = ease(clamp((progress - 0.15) / 0.40, 0, 1));
  const bottomP = ease(clamp((progress - 0.50) / 0.25, 0, 1));
  const footerP = ease(clamp((progress - 0.70) / 0.20, 0, 1));

  // Question section progress variables
  const title1P  = ease(clamp(progress / 0.15, 0, 1));
  const cards1P  = ease(clamp((progress - 0.08) / 0.20, 0, 1));
  const title2P  = ease(clamp((progress - 0.35) / 0.15, 0, 1));
  const cards2P  = ease(clamp((progress - 0.42) / 0.20, 0, 1));

  // Chart calculations
  const W = 900, H = 260;
  const pad = { top: 10, right: 10, bottom: 10, left: 10 };
  const innerW = W - pad.left - pad.right;
  const innerH = H - pad.top - pad.bottom;
  const minV = Math.min(...DATA), maxV = Math.max(...DATA);

  const pts = DATA.map((v, i) => ({
    x: pad.left + (i / (DATA.length - 1)) * innerW,
    y: pad.top + (1 - (v - minV) / (maxV - minV)) * innerH,
  }));

  const barBaseY = pad.top + innerH;
  const visibleCount = Math.max(2, Math.round(chartP * DATA.length));
  const visiblePts = pts.slice(0, visibleCount);
  const polyline = visiblePts.map(p => `${p.x},${p.y}`).join(" ");

  const questions = [
    { img: "/assets/question1.png", text: "Which segments are the most risk-prone?" },
    { img: "/assets/question2.png", text: "Where are the risk hotspots across the country?" },
    { img: "/assets/question3.png", text: "what correlations exist between risk rates and other factors?" },
  ];

  const people = [
    { label: "Truck drivers",      riskRate: "4.75%", meanAge: "30.90", img: "/assets/truck-driver.png" },
    { label: "Dark Store Workers",  riskRate: "2.36%", meanAge: "24.34", img: "/assets/store.png" },
    { label: "Delivery Partners",   riskRate: "3.04%", meanAge: "27.94", img: "/assets/delivery.png" },
  ];

  return (
    <div ref={sectionRef} style={{ height: "680vh", position: "relative" }}>
      <div style={{
        position: "sticky", top: 0, height: "100vh", overflow: "hidden",
        background: `black`,
        display: "flex", flexDirection: "column",
        alignItems: "center", justifyContent: "center",
        padding: "60px 64px 36px",
      }}>
        {/* Fraud Section */}
        <div style={{
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}>
          {/* Title */}
          <div style={{
            textAlign: "center", marginBottom: 22,
            opacity: titleP, transform: `translateY(${lerp(30, 0, titleP)}px)`,
          }}>
            <h2 className="sm:text-[105px] text-[50px]" style={{
              fontFamily: "'Inter','Helvetica Neue',sans-serif",
              fontWeight: 700, color: "white", margin: 0, lineHeight: 1.05,
            }}>
              The Fraud Behind <br className="sm:flex hidden"/>the Workforce
            </h2>
          </div>

          {/* Subtitle */}
          <p style={{
            color: "white", fontSize: "clamp(14px,1.1vw,19px)",
            fontWeight: 600, margin: "0 0 28px", textAlign: "center",
            opacity: titleP, transform: `translateY(${lerp(20, 0, titleP)}px)`,
          }}>
            India's gig workforce has grown from
          </p>

          {/* Chart */}
          <div style={{
            width: "100%", maxWidth: 980,
            opacity: chartP, transform: `translateY(${lerp(20, 0, chartP)}px)`,
          }}>
            <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", overflow: "visible" }}>
              <defs>
                <filter id="glow">
                  <feGaussianBlur stdDeviation="2" result="blur" />
                  <feMerge>
                    <feMergeNode in="blur" />
                    <feMergeNode in="SourceGraphic" />
                  </feMerge>
                </filter>
              </defs>

              {/* Thin vertical white lines from baseline up to each data point */}
              {pts.slice(0, visibleCount).map((p, i) => (
                <line
                  key={`bar-${i}`}
                  x1={p.x} y1={p.y}
                  x2={p.x} y2={barBaseY}
                  stroke="rgba(255,255,255,0.35)"
                  strokeWidth="1.2"
                />
              ))}

              {/* Dashed baseline */}
              <line
                x1={pad.left} y1={barBaseY}
                x2={pad.left + innerW} y2={barBaseY}
                stroke="rgba(255,255,255,0.3)"
                strokeWidth="1"
                strokeDasharray="5 4"
              />

              {/* White line chart */}
              {visiblePts.length > 1 && (
                <polyline
                  points={polyline}
                  fill="none"
                  stroke="white"
                  strokeWidth="2.8"
                  strokeLinejoin="round"
                  strokeLinecap="round"
                  filter="url(#glow)"
                />
              )}

              {/* Red dot on every visible data point */}
              {visiblePts.map((p, i) => (
                <circle
                  key={`dot-${i}`}
                  cx={p.x} cy={p.y}
                  r={i === visiblePts.length - 1 ? 6 : 4}
                  fill="#e53e3e"
                />
              ))}
            </svg>

            {/* Labels row */}
            <div style={{
              display: "flex", alignItems: "flex-start", justifyContent: "space-between",
              marginTop: 8,
              opacity: bottomP, transform: `translateY(${lerp(16, 0, bottomP)}px)`,
            }}>
              <div>
                <div style={{
                  color: "#CE1010", fontSize: "22px", fontWeight: 800,
                  fontFamily: "'Inter',sans-serif", lineHeight: 1.15,
                }}>25.2 lakh</div>
                <div style={{ color: "white", fontSize: 14, marginTop: 2 }}>workers in 2011</div>
              </div>

              <div style={{
                display: "flex", alignItems: "center", gap: 10,
                flex: 1, margin: "6px 20px 0",
              }}>
                <div style={{ flex: 1, height: 1.5, background: "#e53e3e" }} />
                <span style={{ color: "white", fontSize: 11, fontWeight: 700, letterSpacing: 3 }}>TO</span>
                <div style={{ flex: 1, height: 1.5, background: "#e53e3e", position: "relative" }}>
                  <div style={{
                    position: "absolute", right: -7, top: "50%", transform: "translateY(-50%)",
                    width: 0, height: 0,
                    borderTop: "5px solid transparent",
                    borderBottom: "5px solid transparent",
                    borderLeft: "8px solid #e53e3e",
                  }} />
                </div>
              </div>

              <div style={{ textAlign: "right" }}>
                <div style={{
                  color: "#CE1010", fontSize: "22px", fontWeight: 800,
                  fontFamily: "'Inter',sans-serif", lineHeight: 1.15,
                }}>1 crore</div>
                <div style={{ color: "white", fontSize: 13, marginTop: 2 }}>in 2025</div>
              </div>
            </div>

            {/* Source */}
            <div style={{ textAlign: "center", marginTop: 10, marginBottom: 10, opacity: footerP }}>
              <span style={{ color: "rgba(255,255,255,0.38)", fontSize: 13 }}>
                Source:{" "}
                <a
                  href="https://www.niti.gov.in/sites/default/files/2023-06/Policy_Brief_India%27s_Booming_Gig_and_Platform_Economy_27062022.pdf"
                  target="_blank" rel="noreferrer"
                  style={{ color: "rgba(255,255,255,0.58)", textDecoration: "underline", cursor: "pointer" }}
                >Niti Ayog</a>
                {" "}and{" "}
                <a href="https://www.livemint.com/money/personal-finance/indias-gig-economy-in-2025-growth-formalisation-and-financial-inclusion-explained-11753438649777.html"
                  target="_blank" rel="noreferrer"
                  style={{ color: "rgba(255,255,255,0.58)", textDecoration: "underline", cursor: "pointer" }}
                >Mint</a>
              </span>
            </div>
          </div>

          {/* Footer */}
          <p style={{
            color: "white", fontSize: "clamp(15px,1.3vw,21px)",
            textAlign: "center", marginTop: 24, maxWidth: 700,
            opacity: footerP, transform: `translateY(-31px)`,
          }}>
            But as the workforce expands, fraud scales alongside it.
          </p>
        </div>

        {/* Question Section */}
        <div style={{
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          marginTop: 80,
        }}>
          <div style={{
            position: "relative",
            width: "100%",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
          }}>
            <div style={{
              position: "absolute",
              top: 0,
              right: -430,
              zIndex: 0
            }}>
              <img
                src="/assets/Ellipse.png"
                alt="ellipse"
                style={{
                  width: "900px",
                  height: "900px",
                  opacity: 1
                }}
              />
            </div>

            {/* Section 1: Questions */}
            <div style={{ width: "100%", maxWidth: 1300, position: "relative", zIndex: 1 }}>
              <h2 className="sm:text-[105px] text-[50px]" style={{
                fontFamily: "'Inter','Helvetica Neue',sans-serif",
                fontWeight: 700, color: "white",
                margin: "0 0 32px", textAlign: "center", lineHeight: 1.08,
                opacity: title1P, transform: `translateY(${lerp(200, 0, title1P)}px)`,
              }}>
                This section{" "} 
                <span style={{ fontWeight: 700 }}>answers questions like</span>
              </h2>

              <div style={{
                display: "grid",
                gridTemplateColumns: isMobile ? "1fr" : "repeat(3, 1fr)",
                gap: isMobile ? 24 : 20,
                width: "100%",
              }}>
                {questions.map((q, i) => {
                  const cp = ease(clamp((cards1P * 1 - i * 0.15), 0, 1));
                  return (
                    <div key={i} style={{
                      backgroundImage: "linear-gradient(#1d1d1d,#212121)",
                      border: "1px solid white",
                      borderRadius: 16, padding: "18px 20px",
                      display: "flex", alignItems: "center", gap: 20,
                      minHeight: 110,
                      opacity: cp,
                      transform: `translateY(${lerp(30, 0, cp)}px) scale(${lerp(0.96, 1, cp)})`,
                    }}>
                      <div style={{
                        width: 78, height: 78, flexShrink: 0,
                        borderRadius: 14,
                        display: "flex", alignItems: "center", justifyContent: "center",
                      }}>
                        <img src={q.img} alt="" style={{ width: 150, height: 100, objectFit: "contain" }} />
                      </div>
                      <p style={{
                        color: "white", fontSize: "clamp(13px,1.05vw,17px)",
                        fontWeight: 500, margin: 0, lineHeight: 1.5,
                        fontFamily: "'Inter',sans-serif",
                      }}>{q.text}</p>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Divider */}
            <div style={{
              width: "100%", maxWidth: 1300,
              height: 1, background: "rgba(255,255,255,0.08)",
              opacity: title2P,
              marginTop: 40,
            }} />

            {/* Section 2: People */}
            <div style={{ width: "100%", maxWidth: 1100, marginTop: 40, position: "relative", zIndex: 1 }}>
              <h2
                className="bg-gradient-to-r from-[#cdcdcd] to-white bg-clip-text text-transparent sm:text-[105px] text-[50px]"
                style={{
                  fontFamily: "'Inter','Helvetica Neue',sans-serif",
                  fontWeight: 700,
                  margin: "0 0 32px",
                  textAlign: "center",
                  lineHeight: 1.05,
                  opacity: title2P,
                  transform: `translateY(${lerp(24, 0, title2P)}px)`,
                }}
              >
                People in focus
              </h2>

              <div style={{
                display: "grid",
                gridTemplateColumns: isMobile ? "1fr" : "repeat(3, 1fr)",
                gap: isMobile ? 24 : 20,
                width: "100%",
              }}>
                {people.map((p, i) => {
                  const cp = ease(clamp((cards2P * 1 - i * 0.15), 0, 1));
                  return (
                    <div key={i} style={{
                      background: "rgba(255,255,255,0.06)",
                      border: "1px solid rgba(255,255,255,0.1)",
                      borderRadius: 16,
                      padding: "28px 28px 0",
                      display: "flex", flexDirection: "column",
                      position: "relative", overflow: "hidden",
                      minHeight: 280,
                      opacity: cp,
                      transform: `translateY(${lerp(30, 0, cp)}px)`,
                    }}>
                      <div style={{
                        color: "#CE1010", fontSize: "18px",
                        fontWeight: 600, marginBottom: 16,
                        fontFamily: "'Inter',sans-serif",
                      }}>{p.label}</div>

                      <div style={{
                        color: "white", marginTop: "12px", fontSize: "clamp(26px,2.8vw,42px)",
                        fontWeight: 700, lineHeight: 1, fontFamily: "'Inter',sans-serif",
                      }}>{p.riskRate}</div>
                      <div style={{
                        color: "white", fontSize: 18,
                        marginTop: 6, marginBottom: 20,
                      }}>Risk Rate</div>

                      <div style={{ color: "white", fontSize: 18, marginBottom: 19, marginTop: 5 }}>Mean Age</div>
                      <div style={{
                        color: "white", fontSize: "clamp(26px,2.8vw,42px)",
                        fontWeight: 700, lineHeight: 1, fontFamily: "'Inter',sans-serif",
                      }}>{p.meanAge}</div>
                      <div style={{ color: "white", fontSize: 18, marginTop: 8, marginBottom: 20 }}>years</div>

                      <img
                        src={p.img}
                        alt={p.label}
                        style={{
                          position: "absolute",
                          bottom: -10, right: -10,
                          width: "34%", maxWidth: 130,
                          objectFit: "contain",
                          objectPosition: "bottom right",
                          transform: "rotate(10deg)",
                          transformOrigin: "bottom right",
                          opacity: 0.88,
                        }}
                      />
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
